import Form from "./Form";
import Field from "./Field";
import ArrayMap from "./ArrayMap";

export default Form;
export { Form, Field, ArrayMap };
export type { PathsOf, FieldDefinition } from "./models/FormInterface";

import {
  action,
  computed,
  observable,
  autorun,
  runInAction,
} from "mobx";
import { makeObservable } from "./compat";
import { debounce, each, merge } from "lodash";

import Base from "./Base";
import Validator from "./Validator";
import State from "./State";
import Field from "./Field";
import ValidatorInterface from "./models/ValidatorInterface";
import { FieldInterface, FieldConstructor } from "./models/FieldInterface";
import {
  FormInterface,
  FieldsDefinitions,
  FormConfig,
  PathsOf,
} from "./models/FormInterface";
import { FieldPropsEnum } from "./models/FieldProps";
import { OptionsEnum } from "./models/OptionsModel";

export default class Form<F extends Record<string, any> = Record<string, any>> extends Base<F> implements FormInterface<F> {
  name: string;
  override path: any = null;
  extra: Record<string, any> = {};
  validator: ValidatorInterface;

  debouncedValidation: any = null;

  constructor(
    setup: FieldsDefinitions = {},
    {
      name = "",
      options = {},
      plugins = {},
      bindings = {},
      hooks = {},
      handlers = {},
      extra = {},
    }: FormConfig = {}
  ) {
    super();
    makeObservable(this, {
      extra: observable,
      fields: observable,
      flatMapValues: computed,
      error: computed,
      hasError: computed,
      isValid: computed,
      isPristine: computed,
      isDirty: computed,
      isDefault: computed,
      isEmpty: computed,
      focused: computed,
      touched: computed,
      disabled: computed,
      // init: action,
      invalidate: action,
      clear: action,
      reset: action,
      resetValidation: action,
    });

    this.name = name;
    this.extra = extra;
    runInAction(() => (this.$hooks = hooks));
    runInAction(() => (this.$handlers = handlers));

    (globalThis as any).__MOBX_FORMKIT_DEVTOOLS_HOOK__?.emit?.({ type: "form:new", key: this.name, form: this });

    // load data from initializers methods
    const initial = each(
      {
        setup,
        options,
        plugins,
        bindings,
      },
      (val, key) =>
        typeof (this as any)[key] === "function"
          ? merge(val, (this as any)[key].apply(this, [this]))
          : val
    );

    // setup hooks & handlers from initialization methods
    runInAction(() =>
      Object.assign(this.$hooks, (this as any).hooks?.apply(this, [this]))
    );
    runInAction(() =>
      Object.assign(this.$handlers, (this as any).handlers?.apply(this, [this]))
    );

    this.state = new State({
      form: this as any,
      initial: initial.setup,
      options: initial.options,
      bindings: initial.bindings,
    });

    this.validator = new Validator({
      form: this as any,
      plugins: initial.plugins,
    });

    this.initFields(initial.setup);

    this.debouncedValidation = debounce(
      this.validate,
      this.state.options.get(OptionsEnum.validationDebounceWait),
      this.state.options.get(OptionsEnum.validationDebounceOptions)
    );

    // execute validation on form initialization
    this.state.options.get(OptionsEnum.validateOnInit) &&
      this.validator.validate({
        showErrors: this.state.options.get(OptionsEnum.showErrorsOnInit),
      });

    this.execHook(FieldPropsEnum.onInit);

    // handle Form onChange Hook
    autorun(() => this.$changed && this.execHook(FieldPropsEnum.onChange));
  }

  /* ------------------------------------------------------------------ */
  /* COMPUTED */

  get flatMapValues(): Record<string, any> {
    const data: any = {};
    this.each(($field: any) => (data[$field.path] = $field.validatedValue));
    return data;
  }

  get error(): string | null {
    return this.validator.error || this.firstError() || null;
  }

  get hasError(): boolean {
    return !!this.validator.error || this.check(FieldPropsEnum.hasError, true);
  }

  get isValid(): boolean {
    return !this.validator.error && this.check(FieldPropsEnum.isValid, true);
  }

  get isPristine(): boolean {
    return this.check(FieldPropsEnum.isPristine, true);
  }

  get isDirty(): boolean {
    return this.check(FieldPropsEnum.isDirty, true);
  }

  get isDefault(): boolean {
    return this.check(FieldPropsEnum.isDefault, true);
  }

  get isEmpty(): boolean {
    return this.check(FieldPropsEnum.isEmpty, true);
  }

  get focused(): boolean {
    return this.check(FieldPropsEnum.focused, true);
  }

  get touched(): boolean {
    return this.check(FieldPropsEnum.touched, true);
  }

  get disabled(): boolean {
    return this.check(FieldPropsEnum.disabled, true);
  }

  makeField(data: FieldConstructor, FieldClass: typeof Field = Field) {
    return new FieldClass(data);
  }

  /**
   * Select a field by key with type inference.
   * Provides transparent autocomplete for both top-level keys (`keyof F`)
   * AND nested paths (`PathsOf<F>`) without any type annotations needed.
   *
   * @example
   * // Top-level keys — autocomplete from keyof F:
   * form.$('username'); // returns Field<string>
   *
   * @example
   * // Nested paths — autocomplete from PathsOf<F>:
   * form.$('club');                // "club"
   * form.$('club.name');           // "club.name"  ← autocomplete after dot!
   * form.$('members[].firstname'); // "members[].firstname"
   */
  override $(key: keyof F | PathsOf<F>): Field<F[keyof F]> {
    return super.$(key as string) as Field<F[keyof F]>;
  }

  /**
   * Select a field by path.
   * For typed autocomplete, use `$()` instead, which is typed with `keyof F`.
   */
  override select(path: string | number, fields: any = null, isStrict: boolean = true): Field<any> {
    return super.select(path, fields, isStrict) as Field<any>;
  }

  override values(): { [K in keyof F]?: F[K] } {
    return super.values() as { [K in keyof F]?: F[K] };
  }

  /** DEPRECATED
    Init Form Fields and Nested Fields

  init($fields: any = null): void {
    _.set(this, "fields", observable.map({}));

    this.state.initial.props.values = $fields; // eslint-disable-line
    this.state.current.props.values = $fields; // eslint-disable-line

    this.initFields({
      fields: $fields || this.state.struct(),
    });
  }
  */

  invalidate(message: string | null = null, deep: boolean = true): void {
    this.debouncedValidation.cancel();
    this.validator.error =
      message ||
      this.state.options.get(OptionsEnum.defaultGenericError) ||
      null;
    deep &&
      this.each((field: FieldInterface) => field.debouncedValidation.cancel());
  }

  showErrors(show: boolean = true): void {
    this.each((field: FieldInterface) => field.showErrors(show));
  }

  resetValidation(deep: boolean = true): void {
    this.validator.error = null;
    deep && this.each((field: FieldInterface) => field.resetValidation(deep));
  }

  /**
    Clear Form Fields
  */
  clear(deep: boolean = true, execHook: boolean = true): void {
    execHook && this.execHook(FieldPropsEnum.onClear);
    this.$touched = false;
    this.$changed = 0;
    deep && this.each((field: FieldInterface) => field.clear(deep));
  }

  /**
    Reset Form Fields
  */
  reset(deep: boolean = true, execHook: boolean = true): void {
    execHook && this.execHook(FieldPropsEnum.onReset);
    this.$touched = false;
    this.$changed = 0;
    deep && this.each((field: FieldInterface) => field.reset(deep));
  }
}

import * as mobx from "mobx";

// `decorate` was removed in MobX 7 and `makeObservable` does not exist in
// MobX 5. Resolve both lazily through the module namespace so a static
// named import never fails at link time (MISSING_EXPORT) with MobX 7.
const M = mobx as any;

type Annotations = Record<string, any>;

/**
 * `makeObservable` with MobX 5 / 6 / 7 compatibility.
 *
 * MobX 6/7: delegates to the native `makeObservable`.
 * MobX 5: `makeObservable` does not exist (introduced in 6.0). The fallback
 * below re-implements the same semantics with the MobX 5 primitives:
 *
 * 1. every annotated member is materialized as an OWN property of the
 *    instance first (getters/setters are copied down from the prototype
 *    chain — e.g. `changed`/`submitted` live on `Base`, not on `Form`),
 * 2. a single `decorate(instance, ...)` pass applies the corresponding
 *    `observable` / `computed` / `action` decorators.
 *
 * Decorating the instance (instead of the prototype) is required: MobX 5's
 * `decorate` is lazy (`mobxPendingDecorators`) and its initializer accessors
 * recurse infinitely when decorated members live on the prototype, while a
 * computed needs the getter to be an OWN property of the decorated target.
 * `extendObservable` is avoided too — passing `ComputedValue` instances as
 * initial values is no longer supported in 5.15+.
 *
 * All other APIs used across the source (`action`, `set`, `toJS`, `observe`,
 * `intercept`, `reaction`, `autorun`, `runInAction`, `untracked`,
 * `configure`/`enforceActions`, `extendObservable`) exist unchanged in
 * MobX 5.x, 6.x and 7.x, so no other shims are required.
 */
export const makeObservable = (target: any, annotations: Annotations): any => {
  if (typeof M.makeObservable === "function") {
    return M.makeObservable(target, annotations);
  }

  return fallbackMakeObservable(target, annotations);
};

/* istanbul ignore next -- MobX 5 only: no makeObservable in 5.x and no decorate in 6/7, not runnable on the MobX 6/7 test matrix */
function fallbackMakeObservable(target: any, annotations: Annotations): any {
  const members = Object.entries(annotations).filter(([key]) =>
    key in target
  );
  // call sites pass the mobx exports themselves (e.g. `computed`, `action`,
  // `observable`) — compare by value, not by string
  const isComputed = (annotation: any) =>
    annotation === M.computed || annotation === "computed";
  const isAction = (annotation: any) =>
    annotation === M.action || annotation === "action";

  const descriptorFromChain = (key: string) => {
    let currentProto = Object.getPrototypeOf(target);
    let descriptor: PropertyDescriptor | undefined;
    while (currentProto && descriptor === undefined) {
      descriptor = Object.getOwnPropertyDescriptor(currentProto, key);
      currentProto = Object.getPrototypeOf(currentProto);
    }
    return descriptor;
  };

  members.forEach(([key, annotation]) => {
    if (isComputed(annotation)) {
      const own = Object.getOwnPropertyDescriptor(target, key);
      if (!own || typeof own.get !== "function") {
        const chain = descriptorFromChain(key);
        const chainGet =
          chain && typeof chain.get === "function" ? chain.get : null;
        const chainSet =
          chain && typeof chain.set === "function" ? chain.set : null;
        Object.defineProperty(target, key, {
          configurable: true,
          enumerable: chain ? chain.enumerable : false,
          get: chainGet ? () => chainGet.call(target) : () => undefined,
          set: chainSet ? (value: any) => chainSet.call(target, value) : undefined,
        });
      }
    } else if (isAction(annotation)) {
      const value = target[key];
      if (typeof value === "function" &&
          !Object.prototype.hasOwnProperty.call(target, key)) {
        Object.defineProperty(target, key, {
          configurable: true,
          writable: true,
          enumerable: false,
          value,
        });
      }
    }
  });

  const decorators: Record<string, any> = {};
  members.forEach(([key, annotation]) => {
    if (isComputed(annotation)) decorators[key] = M.computed;
    else if (isAction(annotation)) decorators[key] = M.action;
    else decorators[key] = M.observable;
  });

  M.decorate(target, decorators);
  return target;
};

import {
  observable,
  computed,
  action,
  toJS,
  observe,
  intercept,
} from "mobx";
import { makeObservable } from "./compat";
import ArrayMap from "./ArrayMap";
import {
  each,
  forIn,
  get,
  has,
  isPlainObject,
  merge,
  set,
  transform,
} from "lodash";
import { BaseInterface } from "./models/BaseInterface";
import { StateInterface } from "./models/StateInterface";
import { FieldInterface } from "./models/FieldInterface";

import {
  props,
  allowedProps,
  checkPropOccurrence,
  throwError,
  isArrayOfObjects,
  getObservableMapValues,
  maxKey,
  $try,
  isEvent,
  hasIntKeys,
  pathToStruct,
  hasSome,
} from "./utils";

import {
  mergeSchemaDefaults,
  prepareFieldsData,
  parsePath,
  parseInput,
  parseCheckArray,
  parseCheckOutput,
  pathToFieldsTree,
  defaultValue,
} from "./parser";
import {
  AllowedFieldPropsTypes,
  FieldPropsEnum,
  SeparatedPropsMode,
} from "./models/FieldProps";
import { OptionsEnum } from "./models/OptionsModel";
import { ValidateOptions, ValidationHooks } from "./models/ValidatorInterface";
import { SubmitHooks } from "./models/SharedActionsInterface";
export default abstract class Base<
  F extends Record<string, any> = Record<string, any>,
> implements BaseInterface<F> {
  noop = () => {};

  state!: StateInterface;

  fields: ArrayMap = new ArrayMap();
  path: string | undefined | null;

  $submitted: number = 0;
  $submitting: boolean = false;

  $validated: number = 0;
  $validating: boolean = false;

  $clearing: boolean = false;
  $resetting: boolean = false;

  $touched: boolean = false;
  $changed: number = 0;

  $hooks: any = {};
  $handlers: any = {};

  constructor() {
    makeObservable(this, {
      $submitted: observable,
      $submitting: observable,
      $validated: observable,
      $validating: observable,
      $clearing: observable,
      $resetting: observable,
      $touched: observable,
      $changed: observable,
      $hooks: observable,
      $handlers: observable,
      changed: computed,
      submitted: computed,
      submitting: computed,
      validated: computed,
      validating: computed,
      clearing: computed,
      resetting: computed,
      hasIncrementalKeys: computed,
      hasNestedFields: computed,
      size: computed,
      // initialization
      initField: action,
      // actions
      submit: action,
      deepUpdate: action,
      set: action,
      add: action,
      del: action,
      move: action,
    });

    // Any reorder of the fields (also when `fields.move()` is called
    // directly) flags the field and the form as changed. (#657)
    this.fields.onMove = () => {
      this.$changed++;
      this.state.form.$changed++;
    };
  }

  execHook = (name: string, fallback: any = {}, ...args: any[]): any =>
    $try(fallback[name], this.$hooks[name], this.noop).apply(this, [this, ...args]);

  execHandler = (
    name: string,
    args: any,
    fallback: any = undefined,
    hook: any = null,
    execHook = true,
  ): any => [
    $try(
      this.$handlers[name] && this.$handlers[name].apply(this, [this]),
      fallback,
      this.noop,
    ).apply(this, [...args]),
    execHook && this.execHook(hook || name, {}, ...args),
  ];

  get resetting(): boolean {
    return this.hasNestedFields
      ? this.check(FieldPropsEnum.resetting, true)
      : this.$resetting;
  }

  get clearing(): boolean {
    return this.hasNestedFields
      ? this.check(FieldPropsEnum.clearing, true)
      : this.$clearing;
  }

  get submitted(): number {
    return toJS(this.$submitted);
  }

  get submitting(): boolean {
    return toJS(this.$submitting);
  }

  get validated(): number {
    return toJS(this.$validated);
  }

  get validating(): boolean {
    return toJS(this.$validating);
  }

  get hasIncrementalKeys(): boolean {
    return !!this.fields.size && hasIntKeys(this.fields);
  }

  get hasNestedFields(): boolean {
    return this.fields.size !== 0;
  }

  get size(): number {
    return this.fields.size;
  }

  get changed(): number {
    return this.path != null && this.hasNestedFields
      ? this.reduce(
          (acc: number, field: FieldInterface) => acc + field.changed,
          0,
        ) + this.$changed
      : this.$changed;
  }

  /**
    Interceptor
  */
  intercept = (opt: any): any =>
    this.MOBXEvent(
      typeof opt === "function"
        ? { type: "interceptor", call: opt }
        : { type: "interceptor", ...opt },
    );

  /**
    Observer
  */
  observe = (opt: any): any =>
    this.MOBXEvent(
      typeof opt === "function"
        ? { type: "observer", call: opt }
        : { type: "observer", ...opt },
    );

  /**
    Event Handler: On Clear
  */
  onClear = (...args: any): any =>
    this.execHandler(FieldPropsEnum.onClear, args, (e: Event) => {
      isEvent(e) && e.preventDefault();
      (this as any).clear(true, false);
    });

  /**
    Event Handler: On Reset
  */
  onReset = (...args: any): any =>
    this.execHandler(FieldPropsEnum.onReset, args, (e: Event) => {
      isEvent(e) && e.preventDefault();
      (this as any).reset(true, false);
    });

  /**
    Event Handler: On Submit
   */
  onSubmit = (...args: any): any =>
    this.execHandler(
      FieldPropsEnum.onSubmit,
      args,
      (e: Event, o = {}) => {
        isEvent(e) && e.preventDefault();
        this.submit(o);
      },
      null,
      false,
    );

  /**
    Event Handler: On Add
  */
  onAdd = (...args: any): any =>
    this.execHandler(FieldPropsEnum.onAdd, args, (e: Event, val: any) => {
      isEvent(e) && e.preventDefault();
      this.add(isEvent(val) ? null : val, false);
    });

  /**
    Event Handler: On Del
  */
  onDel = (...args: any): any =>
    this.execHandler(FieldPropsEnum.onDel, args, (e: Event, path: string) => {
      isEvent(e) && e.preventDefault();
      this.del(isEvent(path) ? this.path : path, false);
    });

  /******************************************************************
    Initializer
  */
  initFields(initial: any, update: boolean = false): void {
    const fallback = this.state.options.get(OptionsEnum.fallback);
    const $path = (key: string) =>
      [this.path, key].join(".").replace(/^\.+/, "");

    let fields;
    fields = prepareFieldsData(initial, this.state.strict, fallback);
    fields = mergeSchemaDefaults(fields, (this as any).validator);

    // create fields
    forIn(fields, (field, key) => {
      const path = $path(key);
      const $f = this.select(path, null, false);
      if ($f == null) {
        if (fallback) {
          this.initField(key, path, field, update);
        } else {
          const structPath = pathToStruct(path);
          const struct = this.state.struct();
          const found = struct
            .filter((s: any) => s.startsWith(structPath))
            .find(
              (s: any) =>
                s.charAt(structPath.length) === "." ||
                s.substring(structPath.length, structPath.length + 2) ===
                  "[]" ||
                s === structPath,
            );

          if (found) this.initField(key, path, field, update);
        }
      }
    });
  }

  initField(
    key: string,
    path: string,
    data: any,
    update: boolean = false,
    value?: any,
  ): any {
    const initial = this.state.get("current", "props");
    const struct = pathToStruct(path);
    // try to get props from separated objects
    const _try = (prop: string) => {
      const t = get(initial[prop], struct);
      if (
        (
          [
            FieldPropsEnum.input,
            FieldPropsEnum.output,
            FieldPropsEnum.converter,
          ] as string[]
        ).includes(prop) &&
        typeof t !== "function"
      )
        return undefined;

      return t;
    };

    const props = {
      $value:
        value !== void 0
          ? value
          : get(initial[SeparatedPropsMode.values], path),
      $computed: _try(SeparatedPropsMode.computed),
      $label: _try(SeparatedPropsMode.labels),
      $placeholder: _try(SeparatedPropsMode.placeholders),
      $default: _try(SeparatedPropsMode.defaults),
      $initial: _try(SeparatedPropsMode.initials),
      $disabled: _try(SeparatedPropsMode.disabled),
      $deleted: _try(SeparatedPropsMode.deleted),
      $type: _try(SeparatedPropsMode.types),
      $related: _try(SeparatedPropsMode.related),
      $rules: _try(SeparatedPropsMode.rules),
      $options: _try(SeparatedPropsMode.options),
      $bindings: _try(SeparatedPropsMode.bindings),
      $extra: _try(SeparatedPropsMode.extra),
      $hooks: _try(SeparatedPropsMode.hooks),
      $handlers: _try(SeparatedPropsMode.handlers),
      $validatedWith: _try(SeparatedPropsMode.validatedWith),
      $validators: _try(SeparatedPropsMode.validators),
      $observers: _try(SeparatedPropsMode.observers),
      $interceptors: _try(SeparatedPropsMode.interceptors),
      $converters: _try(SeparatedPropsMode.converters),
      $input: _try(SeparatedPropsMode.input),
      $output: _try(SeparatedPropsMode.output),
      $autoFocus: _try(SeparatedPropsMode.autoFocus),
      $ref: _try(SeparatedPropsMode.refs),
      $nullable: _try(SeparatedPropsMode.nullable),
      $autoComplete: _try(SeparatedPropsMode.autoComplete),
    };

    const field = this.state.form.makeField(
      {
        key,
        path,
        struct,
        data,
        props,
        update,
        state: this.state,
      },

      (data && data[FieldPropsEnum.class]) || _try(SeparatedPropsMode.classes),
    );

    this.fields.merge({ [key]: field });

    return field;
  }

  /******************************************************************
    Actions
  */

  validate(opt?: ValidateOptions, obj?: ValidateOptions): Promise<any> {
    const $opt = merge({}, opt, { path: this.path });
    return this.state.form.validator.validate($opt, obj);
  }

  /**
    Submit
  */
  submit(
    hooks: SubmitHooks = {},
    {
      execOnSubmitHook = true,
      execValidationHooks = true,
      validate = true,
    } = {},
  ): Promise<any> {
    const execOnSubmit = () => this.execHook(FieldPropsEnum.onSubmit, hooks);
    const submit = execOnSubmitHook ? execOnSubmit() : undefined;
    this.$submitting = true;
    this.$submitted += 1;

    if (
      !validate ||
      !this.state.options.get(OptionsEnum.validateOnSubmit, this)
    ) {
      return Promise.resolve(submit)
        .then(action(() => (this.$submitting = false)))
        .catch(
          action((err: any) => {
            this.$submitting = false;
            throw err;
          }),
        )
        .then(() => this);
    }

    const exec = (isValid: boolean) =>
      isValid
        ? this.execHook(ValidationHooks.onSuccess, hooks)
        : this.execHook(ValidationHooks.onError, hooks);

    return this.validate({
      showErrors: this.state.options.get(OptionsEnum.showErrorsOnSubmit, this),
    })
      .then(({ isValid }: any) => {
        const handler = execValidationHooks ? exec(isValid) : undefined;
        if (isValid) return Promise.all([submit, handler]);
        const $err = this.state.options.get(
          OptionsEnum.defaultGenericError,
          this,
        );
        const $throw = this.state.options.get(
          OptionsEnum.submitThrowsError,
          this,
        );
        if ($throw && $err) (this as any).invalidate();
        return Promise.all([submit, handler]);
      })
      .then(action(() => (this.$submitting = false)))
      .catch(
        action((err: any) => {
          this.$submitting = false;
          throw err;
        }),
      )
      .then(() => this);
  }

  /**
    Check Field Computed Values
   */
  check(prop: string, deep: boolean = false): boolean {
    allowedProps(AllowedFieldPropsTypes.computed, [prop]);

    return deep
      ? checkPropOccurrence({
          type: props.occurrences[prop],
          data: this.deepCheck(props.occurrences[prop], prop, this.fields),
        })
      : (this as any)[prop];
  }

  deepCheck(type: string, prop: string, fields: any): any {
    const $fields = getObservableMapValues(fields);
    return transform(
      $fields,
      (check: any, field: any) => {
        // Array containers are skipped because most of their props are
        // computed recursively on their nested fields. Some props are not
        // recursive (isDirty/isPristine compare the container value with
        // its initial value) or must aggregate the container itself
        // (isValid/hasError), so they are taken into account for array
        // containers too. (#656, #657)
        const isContainerProp = (
          [
            FieldPropsEnum.isValid,
            FieldPropsEnum.hasError,
            FieldPropsEnum.isDirty,
            FieldPropsEnum.isPristine,
          ] as string[]
        ).includes(prop);
        if (
          isContainerProp ||
          !field.fields.size ||
          !Array.isArray(field.initial)
        ) {
          check.push(field[prop]);
        }

        check.push(
          checkPropOccurrence({
            data: this.deepCheck(type, prop, field.fields),
            type,
          }),
        );

        return check;
      },
      [],
    );
  }

  firstError(): string | null {
    if (!this.state.options.get(OptionsEnum.bubbleUpErrorMessages, this as any))
      return null;
    for (const field of getObservableMapValues(this.fields)) {
      if (field.error) return field.error;
      if (field.fields.size) {
        const nested = field.firstError();
        if (nested) return nested;
      }
    }
    return null;
  }

  /**
    Update Field Values recurisvely
    OR Create Field if 'undefined'
   */
  update(fields: any): void {
    if (!isPlainObject(fields)) {
      throw new Error("The update() method accepts only plain objects.");
    }

    this.deepUpdate(
      prepareFieldsData({ fields }, this.state.strict),
      undefined,
      undefined,
      fields,
    );
  }

  deepUpdate(
    fields: any,
    path: string = "",
    recursion: boolean = true,
    raw?: any,
  ): void {
    each(fields, (field, key) => {
      const $key = has(field, FieldPropsEnum.name) ? field.name : key;
      const $path = `${path}.${$key}`.replace(/^\.+/, "");

      const strictUpdate = this.state.options.get(
        OptionsEnum.strictUpdate,
        this,
      );
      const $field = this.select($path, null, strictUpdate);
      const $container =
        this.select(path, null, false) ||
        this.state.form.select(this.path ?? "", null, false);
      const applyInputConverterOnUpdate = this.state.options.get(
        OptionsEnum.applyInputConverterOnUpdate,
        this,
      );

      if ($field != null && field !== void 0) {
        // an array provided for a field which is not an array container
        // is the field value itself (not a set of nested fields)
        const $rawValue = get(raw, $path);
        const $absPath = [this.path ?? "", $path].join(".").replace(/^\.+/, "");
        if (Array.isArray($rawValue) && !this.isArrayContainer($absPath)) {
          $field.value = parseInput(
            applyInputConverterOnUpdate ? $field.$input : (val) => val,
            {
              fallbackValueOption: this.state.options.get(
                OptionsEnum.fallbackValue,
                this,
              ),
              separated: $rawValue,
            },
          );
          return;
        }

        if (Array.isArray($field.values())) {
          const n: number = Math.max(
            -1,
            ...Object.keys(field.fields || {}).map(Number),
          );
          getObservableMapValues($field.fields).forEach(($f) => {
            if (Number($f.name) > n) {
              $field.$changed++;
              $field.state.form.$changed++;
              $field.fields.delete($f.name);
            }
          });
        }
        if (field?.fields) {
          const fallback = this.state.options.get(OptionsEnum.fallback);
          const x = this.state
            .struct()
            .findIndex((s) =>
              s.startsWith($field.path.replace(/\.\d+\./, "[].") + "[]"),
            );
          if (!fallback && $field.fields.size === 0 && x < 0) {
            $field.value = parseInput(
              applyInputConverterOnUpdate ? $field.$input : (val) => val,
              {
                fallbackValueOption: this.state.options.get(
                  OptionsEnum.fallbackValue,
                  this,
                ),
                separated: get(raw, $path),
              },
            );
            return;
          }
        }
        if (field === null || field.fields == null) {
          $field.value = parseInput(
            applyInputConverterOnUpdate ? $field.$input : (val) => val,
            {
              fallbackValueOption: this.state.options.get(
                OptionsEnum.fallbackValue,
                this,
              ),
              separated: field,
            },
          );
          return;
        }
      }

      if ($container != null && $field == null) {
        // get full path when using update() with select() - FIX: #179
        const $newFieldPath = [this.path, $path].join(".").replace(/^\.+/, "");
        // init field into the container field
        $container.$changed++;
        $container.state.form.$changed++;
        // the value provided by the update wins over the declared values
        $container.initField(
          $key,
          $newFieldPath,
          field,
          true,
          get(raw, $path),
        );
      } else if (recursion) {
        if (has(field, FieldPropsEnum.fields) && field.fields != null) {
          // handle nested fields if defined
          this.deepUpdate(field.fields, $path, true, raw);
        } else {
          // handle nested fields if undefined or null
          const $fields = pathToFieldsTree(this.state.struct(), $path);
          this.deepUpdate($fields, $path, false, raw);
        }
      }
    });
  }

  /**
    Get Fields Props
   */
  get(prop: any = null, strict: boolean = true): any {
    if (prop == null) {
      return this.deepGet(
        [...props.computed, ...props.editable, ...props.validation],
        this.fields,
        strict,
      );
    }

    allowedProps(
      AllowedFieldPropsTypes.all,
      Array.isArray(prop) ? prop : [prop],
    );

    if (typeof prop === "string") {
      if (
        ([FieldPropsEnum.hooks, FieldPropsEnum.handlers] as string[]).includes(
          prop,
        )
      ) {
        return (this as any)[`$${prop}`];
      }

      if (strict && this.fields.size === 0) {
        const retrieveNullifiedEmptyStrings = this.state.options.get(
          OptionsEnum.retrieveNullifiedEmptyStrings,
          this,
        );
        return parseCheckOutput(
          this,
          prop,
          strict ? retrieveNullifiedEmptyStrings : false,
        );
      }

      const value = this.deepGet(prop, this.fields, strict);
      const removeNullishValuesInArrays = this.state.options.get(
        OptionsEnum.removeNullishValuesInArrays,
        this,
      );

      return parseCheckArray(
        this,
        value,
        prop,
        strict ? removeNullishValuesInArrays : false,
      );
    }

    return this.deepGet(prop, this.fields, strict);
  }

  /**
    Get Fields Props Recursively
   */
  deepGet(prop: any, fields: any, strict = true): any {
    const _fieldsArr = getObservableMapValues(fields);
    const _result = transform(
      _fieldsArr,
      (obj: any, field: any) => {
        const $nested = ($fields: any) =>
          $fields.size !== 0 ? this.deepGet(prop, $fields, strict) : undefined;

        Object.assign(obj, {
          [field.key]: { fields: $nested(field.fields) },
        });

        if (typeof prop === "string") {
          const opt = this.state.options;
          const removeProp =
            (opt.get(OptionsEnum.retrieveOnlyDirtyFieldsValues, this) &&
              prop === FieldPropsEnum.value &&
              field.isPristine) ||
            (opt.get(OptionsEnum.retrieveOnlyEnabledFieldsValues, this) &&
              prop === FieldPropsEnum.value &&
              field.disabled) ||
            (opt.get(OptionsEnum.retrieveOnlyEnabledFieldsErrors, this) &&
              prop === FieldPropsEnum.error &&
              field.disabled &&
              field.isValid &&
              (!field.error || !field.hasError)) ||
            (opt.get(OptionsEnum.softDelete, this) &&
              prop === FieldPropsEnum.value &&
              field.deleted);

          if (field.fields.size === 0) {
            delete obj[field.key];
            if (removeProp) return obj;
            const retrieveNullifiedEmptyStrings = this.state.options.get(
              OptionsEnum.retrieveNullifiedEmptyStrings,
              this,
            );
            return Object.assign(obj, {
              [field.key]: parseCheckOutput(
                field,
                prop,
                strict ? retrieveNullifiedEmptyStrings : false,
              ),
            });
          }

          let value = this.deepGet(prop, field.fields, strict);
          if (prop === FieldPropsEnum.value) value = field.$output(value);

          delete obj[field.key];
          if (removeProp) return obj;
          const removeNullishValuesInArrays = this.state.options.get(
            OptionsEnum.removeNullishValuesInArrays,
            this,
          );

          return Object.assign(obj, {
            [field.key]: parseCheckArray(
              field,
              value,
              prop,
              strict ? removeNullishValuesInArrays : false,
            ),
          });
        }

        each(prop, ($prop) =>
          Object.assign(obj[field.key], {
            [$prop]: field[$prop],
          }),
        );

        return obj;
      },
      {} as Record<string, any>,
    );

    // Array fields with integer keys must preserve _entries order
    // (JavaScript Object.assign sorts integer-like keys regardless of insertion order)
    if (
      typeof prop === "string" &&
      _fieldsArr.length > 0 &&
      hasIntKeys(fields)
    ) {
      const keysInResult = new Set(Object.keys(_result));
      return _fieldsArr
        .filter((f) => keysInResult.has(String(f.key)))
        .map((f) => _result[String(f.key)]);
    }

    return _result;
  }

  /**
    Set Fields Props
   */
  set(prop: any, data?: any): void {
    // UPDATE CUSTOM PROP
    if (typeof prop === "string" && data !== void 0) {
      allowedProps(AllowedFieldPropsTypes.editable, [prop]);

      const isPlain = (
        [FieldPropsEnum.hooks, FieldPropsEnum.handlers] as string[]
      ).includes(prop);

      const deep: boolean =
        (data !== null &&
          typeof data === "object" &&
          prop === FieldPropsEnum.value) ||
        (isPlainObject(data) && !isPlain);
      if (deep && this.hasNestedFields)
        return this.deepSet(prop, data, "", true);

      if (prop === FieldPropsEnum.value) {
        const applyInputConverterOnSet = this.state.options.get(
          OptionsEnum.applyInputConverterOnSet,
          this,
        );
        (this as any).value = parseInput(
          applyInputConverterOnSet ? (this as any).$input : (val) => val,
          {
            fallbackValueOption: this.state.options.get(
              OptionsEnum.fallbackValue,
              this,
            ),
            separated: data,
          },
        );
      } else if (isPlain) {
        Object.assign((this as any)[`$${prop}`], data);
      } else {
        set(this, `$${prop}`, data);
      }

      return;
    }

    // NO PROP NAME PROVIDED ("prop" is value)
    if (data == null) {
      if (this.hasNestedFields)
        this.deepSet(FieldPropsEnum.value, prop, "", true);
      else this.set(FieldPropsEnum.value, prop);
    }
  }

  /**
    Set Fields Props Recursively
   */
  deepSet(
    prop: any,
    data: any,
    path: string = "",
    recursion: boolean = false,
  ): void {
    const err = "You are updating a not existent field:";
    const isStrict = this.state.options.get(OptionsEnum.strictSet, this);

    if (data == null) {
      this.each(
        (field: any) =>
          (field.$value = defaultValue({
            fallbackValueOption: this.state.options.get(
              OptionsEnum.fallbackValue,
              this,
            ),
            value: field.$value,
            nullable: field.$nullable,
            type: field.type,
          })),
      );
      return;
    }

    each(data, ($val, $key) => {
      const $path = `${path}.${$key}`.replace(/^\.+/, "");
      // get the field by path joining keys recursively
      const field = this.select($path, null, isStrict);
      // if no field found when is strict update, throw error
      if (isStrict) throwError($path, field, err);
      // update the field/fields if defined
      if (field !== void 0) {
        // update field values or others props
        if ($val !== void 0) {
          field.set(prop, $val, recursion);
        }
        // update values recursively only if field has nested
        if (field.fields.size && $val !== null && typeof $val === "object") {
          this.deepSet(prop, $val, $path, recursion);
        }
      }
    });
  }

  /**
    Add Field
   */
  add(obj?: any, execEvent: boolean = true): any {
    if (isArrayOfObjects(obj)) {
      each(obj, (values) =>
        this.update({
          [maxKey(this.fields)]: values,
        }),
      );

      this.$changed++;
      this.state.form.$changed++;
      execEvent && this.execHook(FieldPropsEnum.onAdd);
      return this;
    }

    // a plain field holding an array value gets the new item appended
    if (
      this.isPlainArrayField() &&
      !has(obj, FieldPropsEnum.key) &&
      !has(obj, FieldPropsEnum.name)
    ) {
      const $values = Array.isArray((this as any).value)
        ? [...((this as any).value as any[])]
        : [];
      $values.push(
        has(obj, FieldPropsEnum.value)
          ? obj[FieldPropsEnum.value]
          : defaultValue({
              fallbackValueOption: this.state.options.get(
                OptionsEnum.fallbackValue,
                this,
              ),
              nullable: (this as any).$nullable,
              type: (this as any).type,
            }),
      );
      this.set(FieldPropsEnum.value, $values);
      this.$changed++;
      this.state.form.$changed++;
      execEvent && this.execHook(FieldPropsEnum.onAdd);
      return this;
    }

    const field = this.createField(obj);

    this.$changed++;
    this.state.form.$changed++;
    execEvent && this.execHook(FieldPropsEnum.onAdd);
    return field;
  }

  /**
    Create a new field into this container (no change counters, no hooks)
  */
  createField(obj?: any, key?: string): any {
    const tree = pathToFieldsTree(
      this.state.struct(),
      this.path ?? "",
      0,
      true,
    );
    const nestedFields = tree[0]?.fields ?? null;

    // An object without field-definition props, whose keys match the
    // nested fields of the container, holds the values of the new item
    // (e.g. add({ name: 'John', qty: 1 })). The 'name' prop is ambiguous:
    // it is treated as a value only when the container defines a nested
    // field called 'name'. (#657)
    const payloadKeys = isPlainObject(obj)
      ? Object.keys(obj).filter((k) => k !== FieldPropsEnum.key)
      : [];
    const isValuesPayload =
      !!nestedFields &&
      isPlainObject(obj) &&
      !has(obj, FieldPropsEnum.value) &&
      !has(obj, FieldPropsEnum.fields) &&
      payloadKeys.length > 0 &&
      (!has(obj, FieldPropsEnum.name) ||
        Object.prototype.hasOwnProperty.call(nestedFields, FieldPropsEnum.name));

    const $key = key ?? obj?.[FieldPropsEnum.key];
    const $fieldKey: any =
      $key !== void 0
        ? $key
        : !isValuesPayload && obj?.[FieldPropsEnum.name] !== void 0
          ? obj[FieldPropsEnum.name]
          : maxKey(this.fields);

    const $path = ($k: any) =>
      [this.path, $k].join(".").replace(/^\.+/, "");
    const field = this.initField(
      $fieldKey,
      $path($fieldKey),
      isValuesPayload ? tree[0] : merge(tree[0], obj),
      false,
      has(obj, FieldPropsEnum.value) ? obj[FieldPropsEnum.value] : void 0,
    );
    const hasValues =
      has(obj, FieldPropsEnum.value) || has(obj, FieldPropsEnum.fields);

    if (isValuesPayload) {
      each(payloadKeys, (fieldName) => {
        const nestedField = field.select(fieldName);
        if (nestedField && !nestedField.hasNestedFields) {
          nestedField.set(FieldPropsEnum.value, (obj as any)[fieldName]);
        }
      });
    } else if (!hasValues) {
      // When the struct defines nested fields and obj is a plain object
      // without field-definition props (key, name), treat obj properties
      // directly as nested field values (e.g. add({ firstname: 'John' }))
      if (
        tree[0]?.fields &&
        isPlainObject(obj) &&
        !hasSome(obj, [FieldPropsEnum.key, FieldPropsEnum.name])
      ) {
        each(obj, (val, fieldName) => {
          const nestedField = field.select(fieldName as string);
          if (nestedField && !nestedField.hasNestedFields) {
            nestedField.set(FieldPropsEnum.value, val);
          }
        });
      } else if (
        !this.state.options.get(OptionsEnum.preserveDeletedFieldsValues, this)
      ) {
        const fallbackValueOption = this.state.options.get(
          OptionsEnum.fallbackValue,
          this,
        );
        field.$value = defaultValue({
          fallbackValueOption,
          value: field.$value,
          nullable: field.$nullable,
          type: field.type,
        });
        field.each(
          (f: any) =>
            (f.$value = defaultValue({
              fallbackValueOption,
              value: f.$value,
              nullable: f.$nullable,
              type: f.type,
            })),
        );
      }
    }

    return field;
  }

  /**
    Checks if the given path refers to an array container
    (a struct entry like `path[]` or `path[].subfield`)
  */
  isArrayContainer(path: string): boolean {
    const struct = this.state.struct();
    if (!Array.isArray(struct)) return false;
    const structPath = (path ?? "").replace(/\.\d+\./g, "[].");
    return struct.some(
      (s: any) => typeof s === "string" && s.startsWith(`${structPath}[]`),
    );
  }

  /**
    Checks if the field is a plain field holding an array value
    (not an array container with nested fields)
  */
  isPlainArrayField(): boolean {
    return (
      !this.hasNestedFields &&
      !this.isArrayContainer(this.path ?? "") &&
      Array.isArray((this as any).value)
    );
  }

  /**
    Applies a value to a field: for fields with nested fields the value is
    applied to the nested fields, otherwise the field value is set
  */
  applyValue($field: any, value: any): void {
    if (value === void 0) return;
    if (isPlainObject(value) && $field.fields.size) {
      each(value, (val, key) => {
        const $nested = $field.select(key);
        if ($nested) {
          $nested.fields.size
            ? this.applyValue($nested, val)
            : $nested.set(FieldPropsEnum.value, val);
        }
      });
      return;
    }
    $field.set(FieldPropsEnum.value, value);
  }

  /**
    Writes an array of values into an array container: the nested fields are
    created, updated and removed to match the given array
  */
  applyArrayValue($field: any, values: any[]): void {
    // remove the nested fields which are not in the new values
    getObservableMapValues($field.fields).forEach(($f: any) => {
      if (Number($f.name) >= values.length) {
        $field.fields.delete($f.name);
      }
    });

    // create or update the nested fields
    values.forEach((value, index) => {
      const key = String(index);
      const $nested = $field.fields.get(key);
      if ($nested) {
        this.applyValue($nested, value);
      } else {
        $field.createField(
          isPlainObject(value) ? value : { [FieldPropsEnum.value]: value },
          key,
        );
      }
    });
  }

  /**
    Del Field
   */
  del($path: string | null = null, execEvent: boolean = true) {
    const isStrict = this.state.options.get(OptionsEnum.strictDelete, this);
    const path = parsePath($path ?? this.path ?? "");
    const fullpath = [this.path ?? "", path ?? ""]
      .join(".")
      .replace(/^\.+|\.+$/g, "");
    const container = this.container($path);
    const keys = path.split(".");
    const lastKey = keys[keys.length - 1];

    if (isStrict && !container.fields.has(lastKey)) {
      const msg = `Key "${lastKey}" not found when trying to delete field`;
      throwError(fullpath, null, msg);
    }

    container.$changed++;
    container.state.form.$changed++;

    if (this.state.options.get(OptionsEnum.softDelete, this)) {
      return this.select(fullpath).set(FieldPropsEnum.deleted, true);
    }

    container.each((field: any) => field.debouncedValidation.cancel());
    execEvent && this.execHook(FieldPropsEnum.onDel);
    return container.fields.delete(lastKey);
  }

  /******************************************************************
    Events
  */

  /**
    MobX Event (observe/intercept)
   */
  MOBXEvent({
    prop = FieldPropsEnum.value,
    key = null,
    path = null,
    call,
    type,
  }: any): void {
    let $prop = key || prop;
    allowedProps(AllowedFieldPropsTypes.observable, [$prop]);
    const $instance = this.select(path || this.path, null, false) || this;

    const $call = (change: any) =>
      call.apply(null, [
        {
          change,
          form: this.state.form,
          path: $instance.path || null,
          field: $instance.path ? $instance : null,
        },
      ]);

    let fn;
    let ffn;

    if (type === "observer") {
      fn = observe;
      ffn = (cb: any) => observe($instance.fields.toArray(), cb); // fields
    }

    if (type === "interceptor") {
      $prop = `$${prop}`;
      fn = intercept;
      ffn = $instance.fields.intercept; // fields
    }
    const $dkey = $instance.path ? `${$prop}@${$instance.path}` : $prop;

    merge((this.state.disposers as any)[type], {
      [$dkey]:
        $prop === FieldPropsEnum.fields
          ? ffn.apply((change: any) => $call(change))
          : (fn as any)($instance, $prop, (change: any) => $call(change)),
    });
  }

  /**
    Dispose MOBX Events
   */
  dispose(opt: any = null): void {
    if (this.path && opt) return this.disposeSingle(opt);
    return this.disposeAll();
  }

  /**
    Dispose All Events (observe/intercept)
   */
  disposeAll(): void {
    const dispose = (disposer: any) => disposer.apply();
    each(this.state.disposers.interceptor, dispose);
    each(this.state.disposers.observer, dispose);
    this.state.disposers = { interceptor: {}, observer: {} };
    return;
  }

  /**
    Dispose Single Event (observe/intercept)
   */
  disposeSingle({ type, key = FieldPropsEnum.value, path = null }: any) {
    const $path = parsePath(path ?? this.path ?? "");
    // eslint-disable-next-line
    if (type === "interceptor") key = `$${key}`; // target observables
    const disposersType = (this.state.disposers as any)[type];
    disposersType[`${key}@${$path}`].apply();
    delete disposersType[`${key}@${$path}`];
  }

  /******************************************************************
    Utils
  */

  /**
    Fields Selector
  */
  select(path: string | number, fields: any = null, isStrict: boolean = true) {
    const $path = parsePath(String(path));
    const keys = $path.split(".");
    const headKey = keys[0];

    keys.shift();

    let $fields =
      fields == null ? this.fields.get(headKey) : fields.get(headKey);

    let stop = false;
    each(keys, ($key) => {
      if (stop) return;
      if ($fields == null) {
        $fields = undefined;
        stop = true;
      } else {
        $fields = $fields.fields.get($key);
      }
    });

    if (isStrict && this.state.options.get(OptionsEnum.strictSelect, this)) {
      throwError(String(path), $fields);
    }

    return $fields;
  }

  /**
    Get Container
   */
  container($path?: string | null) {
    const path = parsePath($path ?? this.path ?? "");
    const cpath = path.replace(/[^./]+$/, "").replace(/^\.+|\.+$/g, "");

    if (!!this.path && $path == null) {
      return cpath !== ""
        ? this.state.form.select(cpath, null, false)
        : this.state.form;
    }

    return cpath !== "" ? this.select(cpath, null, false) : this;
  }

  /**
    Has Field
   */
  has(path: string): boolean {
    return this.fields.has(path);
  }

  /**
    Map Fields
  */
  map(cb: any): ReadonlyArray<FieldInterface> {
    return getObservableMapValues(this.fields).map(cb);
  }

  /**
   * Iterates deeply over fields and invokes `iteratee` for each element.
   * The iteratee is invoked with three arguments: (value, index|key, depth).
   *
   * @param {Function} iteratee The function invoked per iteration.
   * @param {Array|Object} [fields=form.fields] fields to iterate over.
   * @param {number} [depth=1] The recursion depth for internal use.
   * @returns {Array} Returns [fields.values()] of input [fields] parameter.
   * @example
   *
   * JSON.stringify(form)
   * // => {
   *   "fields": {
   *     "state": {
   *       "fields": {
   *         "city": {
   *           "fields": { "places": {
   *                "fields": {},
   *                "key": "places", "path": "state.city.places", "$value": "NY Places"
   *              }
   *           },
   *           "key": "city", "path": "state.city", "$value": "New York"
   *         }
   *       },
   *       "key": "state", "path": "state", "$value": "USA"
   *     }
   *   }
   * }
   *
   * const data = {};
   * form.each(field => data[field.path] = field.value);
   * // => {
   *   "state": "USA",
   *   "state.city": "New York",
   *   "state.city.places": "NY Places"
   * }
   *
   */
  each(iteratee: any, fields: any = null, depth: number = 0) {
    const $fields = fields || this.fields;
    getObservableMapValues($fields).forEach((field: FieldInterface, index) => {
      iteratee(field, index, depth);

      if (field.fields.size !== 0) {
        this.each(iteratee, field.fields, depth + 1);
      }
    });
  }

  reduce(iteratee: any, acc: any): any {
    return getObservableMapValues(this.fields).reduce(iteratee, acc);
  }

  /******************************************************************
    Array Operations
  */

  /**
    Move a field from one index to another (for sortable lists).
   */
  move(fromIndex: number, toIndex: number): void {
    this.fields.move(fromIndex, toIndex);
  }

  /******************************************************************
    Helpers
  */

  /**
    Fields Selector (alias of select)
   */
  $(key: string) {
    return this.select(key);
  }

  /**
    Fields Values (recursive with Nested Fields)
   */
  values() {
    return this.get(FieldPropsEnum.value);
  }

  /**
    Fields Errors (recursive with Nested Fields)
   */
  errors() {
    return this.get(FieldPropsEnum.error);
  }

  /**
    Fields Labels (recursive with Nested Fields)
   */
  labels() {
    return this.get(FieldPropsEnum.label);
  }

  /**
    Fields Placeholders (recursive with Nested Fields)
   */
  placeholders() {
    return this.get(FieldPropsEnum.placeholder);
  }

  /**
    Fields Default Values (recursive with Nested Fields)
   */
  defaults() {
    return this.get(FieldPropsEnum.default);
  }

  /**
    Fields Initial Values (recursive with Nested Fields)
   */
  initials() {
    return this.get(FieldPropsEnum.initial);
  }

  /**
    Fields Types (recursive with Nested Fields)
   */
  types() {
    return this.get(FieldPropsEnum.type);
  }
}

import { observable, runInAction, IObservableArray } from "mobx";

/**
 * ArrayMap: an ordered key-value collection backed by an observable array.
 *
 * Exposes the full ObservableMap-compatible API (get, set, has, delete,
 * merge, forEach, keys, values, entries, intercept, etc.) while
 * maintaining insertion order via an internal observable array.
 *
 * The observable array backing allows array-like operations such as
 * `move(fromIndex, toIndex)` which directly re-orders entries via
 * splice — fully MobX reactive.
 */
export class ArrayMap<K = string, V = any> {
  /** Duck-typing marker for utility code */
  _isArrayMap = true;

  /** Called after a successful `move()` — used to flag the change as dirty */
  onMove?: () => void;

  /** Internal observable array: entries stored as [key, value] pairs */
  private _entries: IObservableArray<[K, V]> = observable.array<[K, V]>([]);

  constructor(entries?: [K, V][] | null) {
    if (entries && entries.length > 0) {
      this._entries.replace(entries);
    }
  }

  // ------------------------------------------------------------------
  // ObservableMap-compatible API
  // ------------------------------------------------------------------

  get size(): number {
    return this._entries.length;
  }

  get(key: K): V | undefined {
    const entry = this._entries.find(([k]) => k === key);
    return entry ? entry[1] : undefined;
  }

  set(key: K, value: V): this {
    const existing = this._entries.find(([k]) => k === key);
    if (existing) {
      existing[1] = value;
    } else {
      this._entries.push([key, value]);
    }
    return this;
  }

  has(key: K): boolean {
    return this._entries.some(([k]) => k === key);
  }

  delete(key: K): boolean {
    const index = this._entries.findIndex(([k]) => k === key);
    if (index !== -1) {
      this._entries.splice(index, 1);
      return true;
    }
    return false;
  }

  clear(): void {
    this._entries.clear();
  }

  keys(): IterableIterator<K> {
    return this._entries.map(([k]) => k)[Symbol.iterator]();
  }

  values(): IterableIterator<V> {
    return this._entries.map(([, v]) => v)[Symbol.iterator]();
  }

  entries(): IterableIterator<[K, V]> {
    return this._entries[Symbol.iterator]();
  }

  forEach(
    callbackfn: (value: V, key: K, map: this) => void,
    thisArg?: any,
  ): void {
    this._entries.forEach(([key, value]) => {
      callbackfn.call(thisArg, value, key, this);
    });
  }

  toJSON(): { [key: string]: V } {
    const result: { [key: string]: V } = {};
    this._entries.forEach(([key, value]) => {
      result[String(key)] = value;
    });
    return result;
  }

  toString(): string {
    return `[object ArrayMap]`;
  }

  merge(other: any): this {
    if (other && typeof other === "object") {
      if (other.forEach && typeof other.forEach === "function") {
        // ObservableMap or Map-like
        other.forEach((value: V, key: K) => {
          this.set(key, value);
        });
      } else if (Array.isArray(other)) {
        // Array of [key, value] pairs
        other.forEach(([key, value]) => {
          this.set(key, value);
        });
      } else {
        // Plain object { key: value }
        Object.keys(other).forEach((key) => {
          this.set(key as any, other[key]);
        });
      }
    }
    return this;
  }

  replace(values: any): this {
    this.clear();
    return this.merge(values);
  }

  get intercept(): any {
    return (this._entries as any).intercept;
  }

  [Symbol.iterator](): IterableIterator<[K, V]> {
    return this._entries[Symbol.iterator]();
  }

  // ------------------------------------------------------------------
  // Array-specific methods
  // ------------------------------------------------------------------

  /**
   * Move an entry from `fromIndex` to `toIndex`.
   *
   * Directly splices the internal observable array, so MobX
   * tracks the change as a single array splice operation.
   */
  move(fromIndex: number, toIndex: number): void {
    runInAction(() => {
      if (fromIndex < 0 || fromIndex >= this._entries.length) return;
      if (toIndex < 0 || toIndex >= this._entries.length) return;
      if (fromIndex === toIndex) return;

      const [entry] = this._entries.splice(fromIndex, 1);
      this._entries.splice(toIndex, 0, entry);
      this.onMove?.();
    });
  }

  /**
   * Expose the underlying observable array for direct MobX
   * observation (e.g. `observe(arr, cb)` from mobx).
   */
  toArray(): Array<[K, V]> {
    return this._entries;
  }
}

export default ArrayMap;

import { has, isEmpty, isPlainObject } from "lodash";
import { values as mobxValues, keys as mobxKeys } from "mobx";
import { FieldInterface } from "./models/FieldInterface";
import { AllowedFieldPropsTypes, FieldPropsEnum, FieldPropsOccurrence } from "./models/FieldProps";
import { props } from "./props";

const getObservableMapValues = (fields: any):
  ReadonlyArray<FieldInterface> => {
  // ArrayMap duck-typing
  if (fields && fields._isArrayMap) {
    const result: FieldInterface[] = [];
    fields.forEach((value: FieldInterface) => result.push(value));
    return result;
  }
  return mobxValues(fields);
};

const getObservableMapKeys = (fields: any):
  ReadonlyArray<any> => {
  // ArrayMap duck-typing
  if (fields && fields._isArrayMap) {
    return Array.from(fields.keys());
  }
  return mobxKeys(fields);
};

const checkObserveItem =
  (change: any) =>
  ({ key, to, type, exec }: any) =>
    change.type === type &&
    change.name === key &&
    change.newValue === to &&
    exec.apply(change, [change]);

const checkObserve = (collection: Record<string, any>[]) => (change: any) =>
  collection.map(checkObserveItem(change));

const checkPropOccurrence = ({ type, data }: any): boolean => {
  let $check: any;
  switch (type) {
    case FieldPropsOccurrence.some: $check = ($data: object) => ($data as any[]).some(Boolean); break;
    case FieldPropsOccurrence.every: $check = ($data: object) => ($data as any[]).every(Boolean); break;
    default: throw new Error('Occurrence not found for specified prop');
  }
  return $check(data);
};

const hasProps = ($type: string, $data: any): boolean => {
  let $props: string[] | null;
  switch ($type) {
    case AllowedFieldPropsTypes.computed:
      $props = props.computed;
      break;
    case AllowedFieldPropsTypes.observable:
        $props = [
          FieldPropsEnum.fields,
          ...props.computed,
          ...props.editable,
        ];
        break;
    case AllowedFieldPropsTypes.editable:
      $props = [
        ...props.editable,
        ...props.validation,
        ...props.functions,
        ...props.handlers,
      ];
      break;
    case AllowedFieldPropsTypes.all:
      $props = [
        FieldPropsEnum.id,
        FieldPropsEnum.key,
        FieldPropsEnum.name,
        FieldPropsEnum.path,
        ...props.computed,
        ...props.editable,
        ...props.validation,
        ...props.functions,
        ...props.handlers,
      ];
      break;
    default:
      $props = null;
  }

  return $data.filter((x: string) => $props!.includes(x)).length > 0;
};

/**
  Check Allowed Properties
*/
const allowedProps = (type: string, data: string[]): void => {
  if (hasProps(type, data)) return;
  const $msg = "The selected property is not allowed";
  throw new Error(`${$msg} (${JSON.stringify(data)})`);
};

/**
  Throw Error if undefined Fields
*/
const throwError = (path: string, fields: any, msg: null | string = null): void => {
  if (fields != null) return;
  const $msg = msg == null ? "The selected field is not defined" : msg;
  throw new Error(`${$msg} (${path})`);
};

const pathToStruct = (path: string): string => {
  let struct;
  struct = path.replace(/\.\d+($|\.)/g, "[].");
  struct = struct.replace("..", ".");
  struct = struct.replace(/^\.+|\.+$/g, "");
  return struct;
};

const isArrayFromStruct = (struct: string[], structPath: string): boolean => {
  if (isArrayOfStrings(struct)) return !!struct
    .filter((s) => s.startsWith(structPath))
    .find((s) => s.substring(structPath.length) === "[]")
    || (struct?.find((e) => e === structPath)?.endsWith('[]') ?? false);
  else return false;
};

const hasSome = (obj: any, keys: any): boolean =>
  keys.some((key: string) => has(obj, key));

const isEmptyArray = (field: any): boolean =>
  isEmpty(field) && Array.isArray(field);

const isArrayOfStrings = (struct: any): boolean =>
  Array.isArray(struct) && struct.every((s: any) => typeof s === 'string');

const isArrayOfObjects = (fields: any): boolean =>
  Array.isArray(fields) && fields.every((f: any) => isPlainObject(f));

const getKeys = (fields: any) =>
  fields ? [...new Set(Object.values(fields).flatMap((values) => values ? Object.keys(values) : []))] : [];

const hasUnifiedProps = ({ fields }: any) =>
  !isArrayOfStrings({ fields }) && hasProps(AllowedFieldPropsTypes.editable, getKeys(fields));

const hasSeparatedProps = (initial: any): boolean =>
  hasSome(initial, props.separated) || hasSome(initial, props.validation);

const allowNested = (field: any, strictProps: boolean): boolean =>
  field !== null && typeof field === 'object' &&
  !(field instanceof Date) &&
  !has(field, FieldPropsEnum.fields) &&
  !has(field, FieldPropsEnum.class) &&
    (!hasSome(field, [
      ...props.editable,
      ...props.handlers,
      ...props.validation,
      ...props.functions,
    ]) || strictProps);

const parseIntKeys = (fields: any) =>
  Array.from(getObservableMapKeys(fields)).map(Number);

const hasIntKeys = (fields: any): boolean =>
  parseIntKeys(fields).every((x: any) => Number.isInteger(x));

const maxKey = (fields: any): number => {
  const keys = parseIntKeys(fields);
  const maxVal = keys.length ? Math.max(...keys) : undefined;
  return maxVal === void 0 ? 0 : maxVal + 1;
};

let _idCounter = 0;
const _localUniqueId = (prefix: string): string => `${prefix}${++_idCounter}`;

const uniqueId = (field: any): string =>
  _localUniqueId([field.path.replace(/\./g, "-"), "--"].join(""));

const isEvent = (obj: any): boolean => {
  if (obj == null || typeof Event === "undefined") return false;
  return obj instanceof Event || obj.target != null;
};

const hasFiles = ($: any): boolean =>
  !!$?.target?.files && $.target.files.length !== 0;

const isBool = ($: any, val: any): boolean =>
  typeof val === 'boolean' && typeof $.target.checked === 'boolean';

const $try = (...args: any[]) => {
  for (const val of args) {
    if (val !== undefined) return val;
  }
  return undefined;
};

export {
  props,
  checkObserve,
  checkPropOccurrence,
  hasProps,
  allowedProps,
  throwError,
  isArrayOfStrings,
  isEmptyArray,
  isArrayOfObjects,
  pathToStruct,
  isArrayFromStruct,
  hasUnifiedProps,
  hasSeparatedProps,
  allowNested,
  parseIntKeys,
  hasIntKeys,
  maxKey,
  uniqueId,
  isEvent,
  hasFiles,
  isBool,
  hasSome,
  $try,
  getObservableMapKeys,
  getObservableMapValues,
};

import { each, get, has, isEmpty, isPlainObject, merge, set, transform } from "lodash";
import { FieldPropsEnum, SeparatedPropsMode } from "./models/FieldProps";
import {
  $try,
  isArrayOfStrings,
  isArrayOfObjects,
  hasUnifiedProps,
  allowNested,
  pathToStruct,
  isEmptyArray,
} from "./utils";

const defaultValue = ({
  type = undefined,
  value = undefined,
  nullable = undefined,
  isEmptyArray = false,
  fallbackValueOption = "",
}: any): null | false | 0 | [] | "" => {
  if (Array.isArray(value) || isEmptyArray) return [];
  if (nullable || value instanceof Date || type === "date" || type === "datetime-local") return null;
  if (typeof value === 'number' || type === "number") return 0;
  if (typeof value === 'boolean' || type === "checkbox") return false;
  if (typeof value === 'string' || type === "file") return "";
  return fallbackValueOption;
};

const parsePath = (path: any): string => {
  let $path = String(path ?? '');
  $path = $path.replace(/\[/g, ".");
  $path = $path.replace(/\]/g, "");
  return $path;
};

const parseInput = (
  input: (...args: any[]) => any,
  { fallbackValueOption = "", type, isEmptyArray, separated, unified, fallback }: any
) =>
  input(
    $try(
      separated,
      unified,
      fallback,
      defaultValue({
        fallbackValueOption,
        type,
        isEmptyArray,
      })
    )
  );

const parseArrayProp = (val: any, prop: string, removeNullishValuesInArrays: boolean): any => {
  const values = Object.values(val);
  const isValProp: boolean = ([
    FieldPropsEnum.value,
    FieldPropsEnum.initial,
    FieldPropsEnum.default,
  ] as string[]).includes(prop)

  if (removeNullishValuesInArrays && isValProp) {
    return values.filter(v => v !== null && v !== undefined && v !== "");
  }

  return values;
};

const parseCheckArray = (field: any, value: any, prop: string, removeNullishValuesInArrays: boolean) => {
  if (field.incremental && value !== null && typeof value === 'object' && isEmpty(value)) return [];
  return field.hasIncrementalKeys ? parseArrayProp(value, prop, removeNullishValuesInArrays) : value;
}

const parseCheckOutput = (field: any, prop: string, retrieveNullifiedEmptyStrings = false) => {
  if (prop === FieldPropsEnum.value || prop.startsWith("value.")) {
    const base = field.$output ? field.$output(field[FieldPropsEnum.value]) : field[FieldPropsEnum.value]
    const value = prop.startsWith("value.") ? get(base, prop.substring(6)) : base
    if (typeof value === 'string' && isEmpty(value) && retrieveNullifiedEmptyStrings) return null
    return value;
  }
  return field[prop];
}

const defineFieldsFromStruct = (struct: string[], add: boolean = false) =>
  struct.reduceRight(
    ($, name) => {
      const obj: any = {};
      if (name.endsWith("[]")) {
        const val = add ? [$] : [];
        obj[name.replace(/\[\]$/, "")] = val;
        return obj;
      }
      // no brakets
      const prev = struct[struct.indexOf(name) - 1];
      const stop = !!prev && prev.endsWith("[]") && struct[struct.length - 1] === name;
      if (!add && stop) return obj;
      obj[name] = $;
      return obj;
    },
    {}
  );

const handleFieldsArrayOfStrings = ($fields: any, add = false) => {
  let fields = $fields;
  // handle array with field struct (strings)
  if (isArrayOfStrings(fields)) {
    fields = transform(
      fields,
      ($obj, $) => {
        const pathStruct = $.split(".");
        // as array of strings (with empty values)
        if (!pathStruct.length) return Object.assign($obj, { [$]: "" });
        // define flat or nested fields from pathStruct
        return merge($obj, defineFieldsFromStruct(pathStruct, add));
      },
      {}
    );
  }
  return fields;
};

const handleFieldsArrayOfObjects = ($fields: any) => {
  let fields = $fields;
  // handle array of objects (with unified props)
  if (isArrayOfObjects(fields)) {
    fields = transform(
      fields,
      ($obj, field) => {
        if (hasUnifiedProps({ fields: { field } }) && !has(field, FieldPropsEnum.name)) return undefined;
        return Object.assign($obj, { [field.name]: field });
      },
      {}
    );
  }
  return fields;
};

const handleFieldsNested = (fields: any, strictProps: boolean = true): any =>
  transform(
    fields,
    (obj, field, key) => {
      if (allowNested(field, strictProps)) {
        // define nested field
        return Object.assign(obj, {
          [key]: {
            fields: isEmptyArray(field) ? [] : handleFieldsNested(field),
          },
        });
      }
      return Object.assign(obj, { [key]: field });
    },
    {}
  );

/* mapNestedValuesToUnifiedValues

FROM:

{
  street: '123 Fake St.',
  zip: '12345',
}

TO:

[{
  name: 'street'
  value: '123 Fake St.',
}, {
  name: 'zip'
  value: '12345',
}]

*/
const mapNestedValuesToUnifiedValues = (data: Record<string, any>): any =>
  isPlainObject(data)
    ? Object.entries(data).map(([name, value]) => ({ value, name }))
    : undefined;

/* reduceValuesToUnifiedFields

FROM:

{
  name: 'fatty',
  address: {
    street: '123 Fake St.',
    zip: '12345',
  },
};

TO:

{
  name: {
    value: 'fatty',
    fields: undefined
  },
  address: {
    value: {
      street: '123 Fake St.',
      zip: '12345'
    },
    fields: [ ... ]
  },
};

*/
const reduceValuesToUnifiedFields = (values: Record<string, any>): Record<string, any> =>
  transform(
    values,
    (obj, value, key) =>
      Object.assign(obj, {
        [key]: {
          value,
          fields: mapNestedValuesToUnifiedValues(value),
        },
      }),
    {}
  );

/*
  Fallback Unified Props to Separated Mode
*/
const handleFieldsPropsFallback = (
  fields: any,
  initial: any,
  fallback: any
) => {
  if (!has(initial, SeparatedPropsMode.values)) return fields;
  // if the 'values' object is passed in constructor
  // then update the fields definitions
  let { values } = initial;
  if (hasUnifiedProps({ fields: initial.fields })) {
    values = reduceValuesToUnifiedFields(values);
  }
  return merge(
    fields,
    transform(
      values,
      (result: any, v, k) => {
        if (Array.isArray(fields[k])) result[k] = v;
        if (!(k in fields) && (!isNaN(Number(k)) || fallback)) result[k] = v;
      },
      {}
    )
  );
};

const mergeSchemaDefaults = (fields: any, validator: any) => {
  if (validator) {
    const schema = get(validator.plugins, "ajv.config.schema");
    if (isEmpty(fields) && schema && !!schema.properties) {
      each(schema.properties, (prop, key) => {
        set(fields, key, {
          value: prop.default,
          label: prop.title,
        });
      });
    }
  }
  return fields;
};

const prepareFieldsData = (
  initial: any,
  strictProps: boolean = true,
  fallback: boolean = true,
) => {
  let fields = merge(
    handleFieldsArrayOfStrings(initial.fields, false),
    handleFieldsArrayOfStrings(initial.struct, false)
  );

  fields = handleFieldsArrayOfObjects(fields);
  fields = handleFieldsPropsFallback(fields, initial, fallback);
  fields = handleFieldsNested(fields, strictProps);

  return fields;
};

const pathToFieldsTree = (
  struct: any,
  path: string,
  n: number = 0,
  add: boolean = false
) => {
  const $struct = (Array.isArray(struct) ? struct : Object.values(struct)).filter((item: any) => typeof item === 'string');
  const structPath = pathToStruct(path);
  const structArray = $struct.filter((item) =>
    item.startsWith(structPath)
  );
  const $tree = handleFieldsArrayOfStrings(structArray, add);
  const $structPath = structPath.replace(/\[\]/g, `[${n}]`);
  const fields = handleFieldsNested(get($tree, $structPath));

  // fix issues #614 & #615
  $struct.length && $struct
    .filter(s => s.startsWith(path + '[]'))
    .map(s => s.substring((path + '[].').length))
    .filter(s => s.endsWith('[]'))
    .map(s => s.substring(0, s.length - 2))
    .forEach(s => {
      const ss = s.split('.')
      let t = fields[0]?.fields
      for (let i = 0; i < ss.length; i++) {
        t = t?.[ss[i]]?.[FieldPropsEnum.fields]
        if (!t) break;
      }
      if (t)
        delete t[0]
    });

  return fields;
};

export {
  defaultValue,
  parseInput,
  parsePath,
  parseArrayProp,
  parseCheckArray,
  parseCheckOutput,
  mergeSchemaDefaults,
  handleFieldsNested,
  handleFieldsArrayOfStrings,
  prepareFieldsData,
  pathToFieldsTree,
};

